Fetch Learner Profile.code:
// Fetch a learner's profile and forward it to an OpenFn webhook.
fetch({
  getEndpoint: 'user', // GET /api/v1/user
  queryParams: { username: $.data.username }, // or { email: ... }
  postUrl: $.configuration.forwardUrl, // where to POST the result
});

Fetch Topic Tree By Kind.code:
// Fetch the topic tree, only exercises, and forward it.
fetch({
  getEndpoint: 'topictree',
  queryParams: { kind: 'Exercise' }, // e.g. 'Topic', 'Video', 'Exercise'
  postUrl: $.configuration.forwardUrl,
});

Fetch Topic Exercises.code:
// List exercises in a topic and forward them.
fetch({
  getEndpoint: `topic/${$.data.topicSlug}/exercises`, // e.g. 'early-math'
  postUrl: $.configuration.forwardUrl,
});

Fetch Topic Videos.code:
// List videos in a topic and forward them.
fetch({
  getEndpoint: `topic/${$.data.topicSlug}/videos`,
  postUrl: $.configuration.forwardUrl,
});

Fetch Single Exercise.code:
// Retrieve one exercise by name and forward it.
fetch({
  getEndpoint: `exercises/${$.data.exerciseName}`, // e.g. 'addition_1'
  postUrl: $.configuration.forwardUrl,
});

Fetch Badges.code:
// List all badges and forward them.
fetch({
  getEndpoint: 'badges',
  postUrl: $.configuration.forwardUrl,
});
